    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)
        m = len(grid[0])
        zero_count = 0
        total = 1

        # Calculate total product modulo 12345
        for i in range(n):
            for j in range(m):
                total = (total * grid[i][j]) % 12345

        # Reset grid and handle zeros
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 0:
                    zero_count += 1

        # If more than one zero, all products are zero
        if zero_count > 1:
            for i in range(n):
                for j in range(m):
                    grid[i][j] = 0
            return grid

        # If exactly one zero, calculate product excluding that zero
        result = [[0] * m for _ in range(n)]

        if zero_count == 1:
            # Find the position of the zero
            zero_pos = None
            for i in range(n):
                for j in range(m):
                    if grid[i][j] == 0:
                        zero_pos = (i, j)
                        break
                if zero_pos:
                    break

            # Calculate total without the zero element
            total_without_zero = total
            if total != 0:
                total_without_zero = total // grid[zero_pos[0]][zero_pos[1]]

            # Set all positions to total mod 12345 except the zero position
            for i in range(n):
                for j in range(m):
                    if (i, j) != zero_pos:
                        result[i][j] = total_without_zero % 12345
                    else:
                        result[i][j] = 0

            # Copy result back to grid
            for i in range(n):
                for j in range(m):
                    grid[i][j] = result[i][j]

        # If no zeros, calculate product excluding each element
        else:
            for i in range(n):
                for j in range(m):
                    # Calculate product excluding current element
                    product = total
                    if total != 0:
                        product = total // grid[i][j]
                    grid[i][j] = product % 12345

        return grid

